// This file is @generated by perseid, vendored from the runtime of the CLI pack.
//! Retries and timeouts: `--retries`, `--no-retry` and `--timeout`, or `<PREFIX>_RETRIES` and
//! `<PREFIX>_TIMEOUT`, which generated code hands the SDK's builder, and `--debug`'s log of each
//! HTTP attempt, which it plugs in as an SDK middleware. The SDK decides what is retried.
use std::{collections::HashMap, io::Write, time::Duration};

use super::{app::Globals, error::CliError};

/// `--timeout`'s parser: seconds, fractions allowed, `0` for no timeout.
pub fn seconds(text: &str) -> Result<Duration, String> {
    let seconds: f64 = text
        .trim()
        .parse()
        .map_err(|_| format!("expected a number of seconds, got `{text}`"))?;
    Duration::try_from_secs_f64(seconds)
        .map_err(|_| format!("expected a non-negative number of seconds, got `{text}`"))
}

/// Fills `--retries` and `--timeout` from `<PREFIX>_RETRIES` and `<PREFIX>_TIMEOUT` when the
/// command line does not set them.
pub fn apply_env(
    globals: &mut Globals,
    env: &HashMap<String, String>,
    prefix: &str,
) -> Result<(), CliError> {
    let var = |suffix: &str| {
        let name = format!("{prefix}_{suffix}");
        let value = env.get(&name).filter(|value| !value.trim().is_empty())?;
        Some((name, value.trim().to_owned()))
    };
    if globals.retries.is_none() && !globals.no_retry {
        if let Some((name, value)) = var("RETRIES") {
            let retries = value.parse().map_err(|_| {
                CliError::usage(format!(
                    "{name}: expected a number of retries, got `{value}`"
                ))
            })?;
            globals.retries = Some(retries);
        }
    }
    if globals.timeout.is_none() {
        if let Some((name, value)) = var("TIMEOUT") {
            let timeout =
                seconds(&value).map_err(|error| CliError::usage(format!("{name}: {error}")))?;
            globals.timeout = Some(timeout);
        }
    }
    Ok(())
}

/// `--debug`'s log of the HTTP attempts of the SDK, one line on stderr per attempt, retries
/// included. `Send + Sync` for the SDK's middleware, so it writes to the process's stderr.
#[derive(Clone, Copy, Debug, Default)]
pub struct Attempts;

impl Attempts {
    /// Logs one attempt: `retry` is the value of the SDK's `*-retry-count` header, `outcome`
    /// the status of the response or why there was none.
    pub fn log(
        &self,
        method: &str,
        url: &str,
        retry: Option<&str>,
        outcome: Result<u16, &str>,
        elapsed: Duration,
    ) {
        let line = line(method, url, retry, outcome, elapsed);
        let _ = writeln!(std::io::stderr(), "{line}");
    }
}

/// `debug: GET https://api.acme.dev/v1/things?…: 503 in 12ms (retry 1)`: the query, which may
/// hold a credential, and the URL's userinfo stay out.
pub fn line(
    method: &str,
    url: &str,
    retry: Option<&str>,
    outcome: Result<u16, &str>,
    elapsed: Duration,
) -> String {
    let url = match url.split_once('?') {
        Some((path, _)) => format!("{}?…", super::app::redact_userinfo(path)),
        None => super::app::redact_userinfo(url),
    };
    let outcome = match outcome {
        Ok(status) => status.to_string(),
        Err(error) => format!("no response ({error})"),
    };
    let retry = match retry {
        Some(count) if count != "0" => format!(" (retry {count})"),
        _ => String::new(),
    };
    format!(
        "debug: {method} {url}: {outcome} in {}ms{retry}",
        elapsed.as_millis()
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn env(vars: &[(&str, &str)]) -> HashMap<String, String> {
        vars.iter()
            .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
            .collect()
    }

    #[test]
    fn seconds_take_fractions_and_zero() {
        assert_eq!(seconds("1.5"), Ok(Duration::from_millis(1500)));
        assert_eq!(seconds("0"), Ok(Duration::ZERO));
        assert!(seconds("-1").is_err());
        assert!(seconds("soon").is_err());
    }

    #[test]
    fn the_environment_fills_what_the_flags_leave() {
        let vars = env(&[("ACME_RETRIES", "5"), ("ACME_TIMEOUT", "2")]);
        let mut globals = Globals::default();
        apply_env(&mut globals, &vars, "ACME").unwrap();
        assert_eq!(globals.retries, Some(5));
        assert_eq!(globals.timeout, Some(Duration::from_secs(2)));

        let mut flags = Globals {
            no_retry: true,
            timeout: Some(Duration::ZERO),
            ..Globals::default()
        };
        apply_env(&mut flags, &vars, "ACME").unwrap();
        assert_eq!((flags.retries, flags.timeout), (None, Some(Duration::ZERO)));

        let error = apply_env(
            &mut Globals::default(),
            &env(&[("ACME_RETRIES", "many")]),
            "ACME",
        )
        .unwrap_err();
        assert_eq!(
            error.message(),
            "ACME_RETRIES: expected a number of retries, got `many`"
        );
    }

    #[test]
    fn attempts_hide_the_query_and_userinfo() {
        let ms = Duration::from_millis(12);
        assert_eq!(
            line(
                "GET",
                "https://k@api.acme.dev/v1/things?api_key=s",
                Some("1"),
                Ok(503),
                ms
            ),
            "debug: GET https://***@api.acme.dev/v1/things?…: 503 in 12ms (retry 1)"
        );
        assert_eq!(
            line(
                "POST",
                "http://localhost/v1/things",
                None,
                Err("connection refused"),
                ms
            ),
            "debug: POST http://localhost/v1/things: no response (connection refused) in 12ms"
        );
    }
}
